package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.BeanDeserializer;
import com.fasterxml.jackson.databind.deser.BeanDeserializerBuilder;
import com.fasterxml.jackson.databind.deser.BeanPropertyMap;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.util.NameTransformer;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Collections;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

/**
 * Unit tests for BeanDeserializer#deserializeFromNull.
 * Since the method is protected, we use a Testable subclass to expose it.
 */
public class BeanDeserializer_deserializeFromNull_TriageGen2Test {

    private BeanDeserializerBuilder builder;
    private BeanDescription beanDescription;
    private BeanPropertyMap beanPropertyMap;
    private TestableBeanDeserializer deserializer;
    private JsonParser mockParser;
    private DeserializationContext mockContext;

    // Testable subclass to access protected methods and manipulate internal state
    public static class TestableBeanDeserializer extends BeanDeserializer {
        private boolean vanillaProcessing;

        protected TestableBeanDeserializer(BeanDeserializerBuilder builder, BeanDescription beanDesc, BeanPropertyMap properties) {
            super(builder, beanDesc, properties, Collections.emptySet(), Collections.emptySet(), false, false);
            this.vanillaProcessing = false;
        }

        public void setVanillaProcessing(boolean vanillaProcessing) {
            this.vanillaProcessing = vanillaProcessing;
        }

        @Override
        public Class<?> handledType() {
            return Object.class;
        }

        // Expose protected method for testing
        @Override
        public Object deserializeFromNull(JsonParser p, DeserializationContext ctxt) throws IOException {
            return super.deserializeFromNull(p, ctxt);
        }

        // Mocking the internal logic dependencies
        @Override
        protected Object vanillaDeserialize(JsonParser p, DeserializationContext ctxt, JsonToken t) throws IOException {
            return "vanilla_result";
        }

        @Override
        protected Object deserializeFromObject(JsonParser p, DeserializationContext ctxt) throws IOException {
            return "object_result";
        }
    }

    @Before
    public void setUp() {
        builder = mock(BeanDeserializerBuilder.class);
        beanDescription = mock(BeanDescription.class);
        beanPropertyMap = mock(BeanPropertyMap.class);
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);

        deserializer = new TestableBeanDeserializer(builder, beanDescription, beanPropertyMap);
    }

    @Test
    public void testDeserializeFromNull_WhenRequiresCustomCodecFalse_ReturnsHandleUnexpectedToken() throws IOException {
        // Arrange
        when(mockParser.requiresCustomCodec()).thenReturn(false);
        String expectedErrorMessage = "Unexpected token";
        when(mockContext.handleUnexpectedToken(eq(Object.class), eq(mockParser))).thenReturn(expectedErrorMessage);

        // Act
        Object result = deserializer.deserializeFromNull(mockParser, mockContext);

        // Assert
        assertEquals(expectedErrorMessage, result);
        verify(mockContext).handleUnexpectedToken(Object.class, mockParser);
    }

    @Test
    public void testDeserializeFromNull_WhenRequiresCustomCodecTrue_AndVanillaProcessingTrue_ReturnsVanillaResult() throws IOException {
        // Arrange
        when(mockParser.requiresCustomCodec()).thenReturn(true);
        deserializer.setVanillaProcessing(true);

        // Act
        Object result = deserializer.deserializeFromNull(mockParser, mockContext);

        // Assert
        assertEquals("vanilla_result", result);
        // Verification of TokenBuffer logic is implicit via the mocked vanillaDeserialize return value
    }

    @Test
    public void testDeserializeFromNull_WhenRequiresCustomCodecTrue_AndVanillaProcessingFalse_ReturnsObjectResult() throws IOException {
        // Arrange
        when(mockParser.requiresCustomCodec()).thenReturn(true);
        deserializer.setVanillaProcessing(false);

        // Act
        Object result = deserializer.deserializeFromNull(mockParser, mockContext);

        // Assert
        assertEquals("object_result", result);
    }

    @Test(expected = IOException.class)
    public void testDeserializeFromNull_WhenHandleUnexpectedTokenThrowsException() throws IOException {
        // Arrange
        when(mockParser.requiresCustomCodec()).thenReturn(false);
        when(mockContext.handleUnexpectedToken(any(), any())).thenThrow(new IOException("IO Error"));

        // Act
        deserializer.deserializeFromNull(mockParser, mockContext);
    }
}
